head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05919";
scwin.secugrpId = "";       // 증권그룹ID (AS-IS arr[0]) — 이 화면에서는 쓰지 않음
scwin.mktId = "";           // 시장구분코드 (AS-IS arr[1]) — 사유 목록 조회 조건(§10 #1)
scwin.bzProcsNo = "";       // 업무처리번호 (AS-IS arr[2]) — 비어 있으면 신규, 있으면 수정. 신규 등록 성공 뒤 확정
scwin.gubun = "3";          // 종목선택 팝업 구분값 — "3" 전체 (AS-IS gubun, §8 #2)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.savedState = "";      // 상세를 채운 직후의 값 — 안내문작성 전 변경 여부 판정용 (AS-IS dts_Mst.IsUpdated || dts_Rsn.IsUpdated)
scwin.LIST_BZ_TP_CD = "313";            // 상장업무유형 — 조기종료에 의한 상장폐지 (AS-IS LIST_BZ_TP_CD "313")
scwin.ISUR_CD = "99999";                // 발행기관코드 — ELW 는 종목별 처리라 고정값 (AS-IS ISUR_CD "99999")
scwin.DEFAULT_RSN_CD = "690019";        // 신규 기본 상장폐지사유 — 권리행사조건의 달성(조기종료 발생)
scwin.BZ_PROCS_NO_LEN = 14;             // 업무처리번호 자릿수 (AS-IS fr_bz_procs_no.length != 14 → MSG-0010)
scwin.DSCL_FORM_CD = "68955D";          // 공시안내문 서식코드 (AS-IS arr[0])
scwin.DSCL_MKT_ID = "1";                // 공시안내문 시장구분 (AS-IS arr[3] '1')
scwin.DSCL_TITLE = "조기종료에 의한 상장폐지";  // 공시안내문 부가 문구 (AS-IS arr[5])
// 원본 : /lstproc/ULDSTF05919.gfm (ELW 조기종료에 의한 상장폐지 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05916 상장폐지)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규는 현재일(조기종료 발생 기준일)로 대상 종목을 조회하거나 [종목선택] 팝업으로 종목을 담아 등록한다.
 *  - 수정은 상세(MST)·등록 종목을 조회하고, 상장폐지일이 지나지 않았으면 수정·삭제·안내문작성을 할 수 있다.
 *  - 통신·데이터 정의는 ULDSTF05919_API.md 명세 기준(select-new-isu-knock-out·select-isu·select-mst·register·modify·remove).
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF05919/ULDSTF05919.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)

// 화면 상태값

// 고정값
// 상장폐지 사유 목록 — TODO: AS-IS listCode(MKT, RSN=05) 대응 API 가 명세에 없어 기본 사유 한 건만 둔다(근거규정은 캡처 값) (§10 #1)
scwin.RSN_LIST = [
    { code : "690019", name : "권리행사조건의 달성(조기종료 발생)", regl : "유가증권시장상장규정 제143조" }
];

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 달력·Enter 키 바인딩 → 사유 목록 → 신규 준비(scwin.initNewForm) 또는 수정 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    btn_Search.setDisabled(true);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.secugrpId = param.secugrpId ?? "";        // AS-IS arr[0]
    scwin.mktId = param.mktId ?? "";                // AS-IS arr[1]
    scwin.bzProcsNo = param.bzProcsNo ?? "";        // AS-IS arr[2]
    scwin.gubun = param.gubun || scwin.gubun;       // AS-IS arr[4] (원본은 arr[3] 을 읽는 결함 — §8 #2)
    dma_search.set("baseDd", param.baseDd ?? "");   // AS-IS arr[3] 최종거래일 또는 당일자

    // 3) 달력 형식 검사 · 조회조건 Enter 키 (규칙 22·37)
    $c.date.checkCalendarFormat(edt_Dd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_DelistDd, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_1, scwin.btn_Search_onclick);
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 4) 상장폐지 사유 목록 (원본 fn_get_rsn_cd — 동기 조회)
    scwin.loadRsnList();

    // 5) 업무처리번호 유무로 신규 준비 또는 수정 조회
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
    } else {
        scwin.setEditMode();
        await scwin.selectDetail();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 버튼 클릭(조회조건 Enter 키 포함) — 현재일로 조기종료 발생 대상 종목을 조회한다. (원본 fn_get_isu_cd — §5.1)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.searchNewIsu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목선택 클릭 — ELW 종목선택 팝업 결과로 그리드를 통째로 바꾼다. (§6.4, §1.4 업무 3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.cmb_Rsn_Cd_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지사유를 사용자가 바꾸면 그 사유의 근거규정을 근거규정 입력란에 채운다.
 * onviewchange 는 사용자 조작에만 발생하므로 원본의 isFirstLoad 가드가 필요 없다. (원본 cmb_Rsn_Cd OnSelChange2 — §6.3)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onviewchange = async function (info) {
    try {
        scwin.applyGrndRegul();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.cmb_Rsn_Cd_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05919.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.searchNewIsu
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규: 현재일(조기종료 발생 기준일)로 대상 종목을 조회해 그리드를 바꾼다. 수정 모드에서는 하지 않는다(원본 버튼 잠금).
 * (원본 fn_get_isu_cd — §5.1)
 * @returns
 * @hidden N
 */
scwin.searchNewIsu = async function () {
    // 원본은 [조회]가 [저장]과 같이 켜지고 꺼졌다(setCopyInfo) — Enter 키로 들어와도 수정 모드면 조회하지 않는다.
    if (!$c.util.isEmpty(scwin.bzProcsNo)) return;

    const baseDd = String(dma_search.get("baseDd") ?? "");
    if (baseDd.length !== 8) {
        await $c.win.alert("[조기종료일]을 정확히 입력하세요.");
        edt_Dd.focus();
        return;
    }

    const sbmOptions = {
        id : "sbm_searchNewIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-new-isu-knock-out",
        // 명세 target 은 dlt_newIsuKnockOut=body — columnInfo 가 같은 그리드 목록 dlt_isu 로 받는다(§5.1)
        target : "dlt_isu=body",
        gridview : "grd_isu",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { baseDd : baseDd });
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정: 업무처리번호로 상세(MST)와 등록 종목을 차례로 조회하고, 상장폐지일로 버튼 상태를 정한다.
 * (원본 fn_search + dts_Mst OnLoadCompleted — §5.2, §5.3)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function () {
    const mstOptions = {
        id : "sbm_selectMst",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-mst",
        target : "dma_mst=body",
        isProcessMsg : false
    };

    const mstResult = await $c.sbm.executeDynamic(mstOptions, { bzProcsNo : scwin.bzProcsNo });
    if (mstResult?.skipped) return;     // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 버튼을 모두 잠근다 — 등록 뒤 재조회 실패면 수정 버튼이 엉뚱한 상태로 남지 않게 명시적으로 잠근다.
    if (!mstResult.responseJSON?.success) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    const isuOptions = {
        id : "sbm_selectIsu",
        method : "get",
        action : "/api/listing/lstproc/elw/delisting/detail/select-isu",
        target : "dlt_isu=body",
        gridview : "grd_isu",
        isProcessMsg : false
    };

    const isuResult = await $c.sbm.executeDynamic(isuOptions, { bzProcsNo : scwin.bzProcsNo });
    if (isuResult?.skipped) return;

    if (!isuResult.responseJSON?.success) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    // 사유 콤보는 dma_mst.delistRsnCd 바인딩으로 따라온다(원본 BindColVal). 근거규정은 저장된 값을 그대로 둔다.
    scwin.savedState = scwin.getEditState();

    // 상장폐지일이 오늘 이후면 update(수정·삭제·안내문작성), 지났으면 error(처리 버튼 없음)
    $c.stf.setButtonSetWithDate(edt_DelistDd, false, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록(I)·수정(U). 명세 요청 정의(dma_save · dlt_saveIsuList)에 담아 보낸다 — setJSON 이 정의된 키만 남겨 명세 밖 값은 보내지 않는다.
 * 전달 방식은 명세대로 머리 dataMap 은 requestData 최상위 필드로, 종목 목록은 requestData.isuList 로 보낸다. (원본 fn_save_trs + trs — §5.4, §5.5)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @param {String} bzProcsNo 업무처리번호 (등록은 새로 받은 번호, 수정은 scwin.bzProcsNo)
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const isInsert = (trJob === "I");
    const jobNm = isInsert ? "저장" : "수정";

    // TODO: 원본이 보내던 MKTACT_APPL_OBJ_TP_CD "1"(종목별)·SCREN_ID·DIV_IDX 는 명세에 없음 (§10 #4)
    dma_save.setEmptyValue();
    dma_save.setJSON({
        listBzTpCd : scwin.LIST_BZ_TP_CD,
        bzProcsNo : bzProcsNo,
        isurCd : scwin.getIsurCd(),
        delistDd : dma_mst.get("delistDd"),
        delistRsnCd : dma_mst.get("delistRsnCd"),
        delistRsnDsc : dma_mst.get("delistRsnDsc"),     // TODO: 원본은 사유명을 따로 보내지 않음 — 콤보 사유명을 넣을지 확인 (§10 #5)
        ulyDelistRsnCd : "",                            // 명세: ULDSTF05917 기초자산 구분일 때만
        ulyDelistBzProcsNo : "",
        grndRegulNm : dma_mst.get("grndRegulNm"),
        remk : dma_mst.get("remk")
    });
    dlt_saveIsuList.setJSON(dlt_isu.getAllJSON());

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : isInsert ? "/api/listing/lstproc/elw/delisting/detail/register" : "/api/listing/lstproc/elw/delisting/detail/modify",
        mediatype : "application/json",
        target : "dma_result=body",
        isProcessMsg : false
        // ref 는 쓰지 않는다 — 명세: 요청 정의 데이터를 requestData 로 전달
    };

    const requestData = {
        ...dma_save.getJSON(),
        isuList : dlt_saveIsuList.getAllJSON()
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isDone(result)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 원본 OnSuccess → fn_search(): 등록이면 받은 번호로 수정 모드가 된다. 응답 번호가 있으면 그것을 쓴다.
    if (isInsert) {
        scwin.bzProcsNo = String(dma_result.get("bzProcsNo") || bzProcsNo);
        scwin.setEditMode();
    }
    await scwin.selectDetail();
};

/**
 * @method
 * @name scwin.deleteTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 명세 remove 요청(listBzTpCd·bzProcsNo·isurCd)을 보내고, 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 다시 조회한다. (§5.6)
 * @returns
 * @hidden N
 */
scwin.deleteTrs = async function () {
    const sbmOptions = {
        id : "sbm_deleteTrs",
        method : "post",
        action : "/api/listing/lstproc/elw/delisting/detail/remove",
        mediatype : "application/json",
        target : "dma_result=body",
        isProcessMsg : false
    };

    const requestData = {
        listBzTpCd : scwin.LIST_BZ_TP_CD,
        bzProcsNo : scwin.bzProcsNo,
        isurCd : scwin.getIsurCd()
    };

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isDone(result)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 준비. 입력과 종목 목록을 비우고 기본 사유(조기종료 발생)·근거규정을 채운 뒤 현재일 조회와 [저장]을 켠다.
 * (원본 fn_new_onload + dts_Mst OnLoadCompleted 신규 분기 — §3)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dlt_isu.removeAll();

    dma_mst.set("isurCd", scwin.ISUR_CD);
    dma_mst.set("delistRsnCd", scwin.DEFAULT_RSN_CD);
    scwin.applyGrndRegul();

    edt_Dd.setReadOnly(false);
    btn_Search.setDisabled(false);

    scwin.savedState = scwin.getEditState();
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.setEditMode
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정 모드 화면 상태. 현재일은 읽기 전용, [조회]는 잠근다. (원본 edt_Dd.ReadOnly = true, btn_Dd 클릭 무시, setCopyInfo — §4)
 * @returns
 * @hidden N
 */
scwin.setEditMode = function () {
    edt_Dd.setReadOnly(true);
    btn_Search.setDisabled(true);
};

/**
 * @method
 * @name scwin.loadRsnList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지사유 콤보 목록을 채운다. (원본 fn_get_rsn_cd — listCode MKT·RSN=05, 명세 없음 §10 #1)
 * @returns
 * @hidden N
 */
scwin.loadRsnList = function () {
    // TODO: 사유 목록 API(시장구분 scwin.mktId · 사유구분 05) 명세가 오면 조회로 바꾼다 (§10 #1)
    dlt_rsn.setJSON(scwin.RSN_LIST);
};

/**
 * @method
 * @name scwin.applyGrndRegul
 * @author Inswave
 * @date 2026. 10. 29
 * @description 선택한 상장폐지사유의 근거규정을 근거규정 입력란에 채운다. (원본: 콤보 선택 행의 REGL 을 txb_GrndRegulNm 에 — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyGrndRegul = function () {
    const rsnCd = dma_mst.get("delistRsnCd");
    const rsn = dlt_rsn.getAllJSON().find(row => row.code === rsnCd);
    dma_mst.set("grndRegulNm", rsn?.regl ?? "");
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 입력 폼(상세·사유) 값의 스냅샷. 안내문작성 전 변경 여부 판정에 쓴다(종목 목록은 원본도 제외).
 * @returns {String} 상세 값 JSON 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    return JSON.stringify(dma_mst.getJSON());
};

/**
 * @method
 * @name scwin.getIsurCd
 * @author Inswave
 * @date 2026. 10. 29
 * @description 전문에 넣을 발행기관코드. 수정은 조회 값, 신규는 고정값 99999 다.
 * @returns {String} 발행기관코드
 * @hidden N
 */
scwin.getIsurCd = function () {
    return dma_mst.get("isurCd") || scwin.ISUR_CD;
};

/**
 * @method
 * @name scwin.isDone
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록·수정·삭제 응답 판정. 통신이 성공하고 completeYn 이 오지 않았거나 참이면 true. (명세: completeYn 은 boolean)
 * @param {Object} result executeDynamic 결과
 * @returns {Boolean} 처리 성공 여부
 * @hidden N
 */
scwin.isDone = function (result) {
    if (!result?.responseJSON?.success) return false;

    // TODO: register·remove 는 명세에 응답 정의가 없어 completeYn 이 비어 오면 success 만으로 판정한다 (§10 #6)
    const completeYn = String(dma_result.get("completeYn") ?? "");
    return completeYn === "" || completeYn === "true" || completeYn === "Y";
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다. (§6.1)
 *  1) 종목 1건 이상  2) 상장폐지일 필수·날짜, 익일 이후  3) 근거규정 필수·200 byte  4) 기타 2000 byte
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isu.getRowCount() === 0) {
        await $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }

    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_DelistDd : { required : true, format : "date", name : "상장폐지일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, dateOptions)) return false;

    // 상장폐지일은 익일 이후 (원본 checkDdTm("DD", edt_DelistDd, "상장폐지", false) — pcc 함수는 Gauce 속성 .text 를 읽어 쓰지 않는다)
    if (dma_mst.get("delistDd") <= scwin.curDate) {
        await $c.win.alert("[상장폐지일]을 익일 이후로 입력하세요.");
        edt_DelistDd.focus();
        return false;
    }

    const textOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_GrndRegulNm : { required : true, maxLengthB : 200, name : "근거규정" },
            txa_Remk : { maxLengthB : 2000, name : "기타" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, textOptions)) return false;

    return true;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록용 업무처리번호를 새로 받는다. pcc 응답 형태(문자열 / { body } / { body : { bzProcsNo } })를 모두 받아 문자열로 돌려준다.
 * (원본 fn_getNewBzProcNo(dts_BzProcsNo) — §5.4)
 * @returns {Promise<String>} 업무처리번호 (실패 시 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 명세 register 의 bzProcsNo 가 화면 채번인지 서버 채번인지 적혀 있지 않다 — 원본대로 화면에서 채번 (§10 #3)
    const res = await $c.stf.getNewBzProcNo();
    const body = (res !== null && typeof res === "object") ? res.body : res;
    const no = (body !== null && typeof body === "object") ? body.bzProcsNo : body;
    return String(no ?? "");
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description ELW 종목선택(전체) 팝업(ULDSTF92023_1)을 현재 그리드와 함께 열고, 고른 결과로 그리드를 바꾼다.
 * (원본 fn_GetParIsu/fn_SetParIsu 바꿔 끼우기 + fn_PopFindElwCodeAll — §6.4, 가이드 §6.5)
 * pcc $c.lc.popFindElwCodeAll 은 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const data = {
        isurCd : scwin.ISUR_CD,             // AS-IS arrPar[0] Isur_cd "99999"
        gubun : scwin.gubun,                // AS-IS arrPar[1] — "3" 전체
        isuList : dlt_isu.getAllJSON()      // AS-IS CopyDataSet(dts_Isu, param_dts)
    };
    const options = {
        id : "ULDSTF92023_1",
        popupName : "종목선택",
        width : 510,
        height : 430,
        type : "pageFramePopup"
    };

    // TODO: 92023_1 전환본이 없어 경로·반환 키(list)·행 컬럼은 가정 (§10 #7)
    const result = await $c.win.openPopup("/ui/listingcommon/ULDSTF92023_1.xml", options, data);

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 목록 필드로 판정한다.
    if (!Array.isArray(result?.list)) return;

    // AS-IS fn_SetParIsu: 선택 결과로 그리드 전체를 바꾼다.
    dlt_isu.setJSON(result.list);
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록. 검증 → 확인 → 채번(14자리 아니면 MSG-0010) → 등록 순서. 채번이 확인보다 뒤라 취소한 건에는 번호가 소비되지 않는다. (원본 fn_save — §6.5)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== scwin.BZ_PROCS_NO_LEN) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    await scwin.saveTrs(scwin.trJob, bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정. 검증 → 확인 → 수정 순서. 원본처럼 바뀐 내용이 없어도 보낸다. (원본 fn_update — §6.6)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob, scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.7)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.deleteTrs();
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성 팝업(ULDSTF92024)에 넘길 data. (원본 fn_dscl 의 임시 fn_GetPar — arr[0]~[5] + CopyDataSet 2종, §6.8)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    return {
        formCd : scwin.DSCL_FORM_CD,        // AS-IS arr[0] "68955D"
        bzProcsNo : scwin.bzProcsNo,        // AS-IS arr[1] fr_bz_procs_no
        isurCd : scwin.getIsurCd(),         // AS-IS arr[2] "99999"
        mktId : scwin.DSCL_MKT_ID,          // AS-IS arr[3] '1'
        msg : "",                           // AS-IS arr[4] ''
        title : scwin.DSCL_TITLE,           // AS-IS arr[5] '조기종료에 의한 상장폐지'
        isu : dlt_isu.getAllJSON(),         // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        // AS-IS CopyDataSet(dts_Mst, param_dts_mst) + DELIST_RSN_NM = cmb_Rsn_Cd.text
        mst : [{ ...dma_mst.getJSON(), delistRsnNm : cmb_Rsn_Cd.getText() }]
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성. 상세를 고친 뒤 저장하지 않았으면 안내하고, 아니면 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. (원본 fn_dscl — §6.8, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    // MSG-0022 "변경된 항목이 있습니다. 수정후에 안내문작성을 다시 클릭하세요." (원본 dts_Mst.IsUpdated || dts_Rsn.IsUpdated)
    if (scwin.getEditState() !== scwin.savedState) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 29
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.8, §10 #8, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 메시지 [5] 공시제목 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.8)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
